import { ChangeDetectionStrategy, Component, computed, viewChild } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-19",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent ],
    templateUrl: "./feature-19.component.html"
})
export class Feature019Component {
    isActive = false;
    count = 5;
    title = "Title 19";
    statusVariant: PillVariant = "success";
    disableTooltip = true;

    private readonly firstPill = viewChild(PillComponent);
    private readonly card = viewChild(CardComponent);
    readonly quiet = computed(() => {
        if (this.disableTooltip) return true;
        const card = this.card()?.disableTooltip() ?? false;
        const pill = this.firstPill()?.disableTooltip() ?? false;
        return card || pill;
    });
}

import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-15",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent ],
    template: `
        <app-card
            heading="Feature 15"
            [disableTooltip]="true"
        >
            <!-- disableTooltip above is the card's flag: no hint on the title -->
            <app-pill
                label="Plain"
                variant="warning"
                disableTooltip
            />
            <app-pill
                [label]="title"
                [variant]="count > 3 ? 'success' : isActive ? 'warning' : 'info'"
                [disableTooltip]="!(isActive && count > 1)"
            />
            <app-pill [variant]="statusVariant" label="Nested" [disableTooltip]="false" />
            <app-fancy-pill icon="bolt" label="Fancy" disableTooltip></app-fancy-pill>
        </app-card>
        <app-card #summary heading="Summary" [disableTooltip]="!isActive" />
        <small>Summary hint: {{ summary.disableTooltip() ? 'off' : 'on' }}</small>
    `
})
export class Feature015Component {
    isActive = false;
    count = 1;
    title = "Title 15";
    statusVariant: PillVariant = "success";
}

